<?php
declare(strict_types=1);
require_once __DIR__.'/auth_check.php';require_once __DIR__.'/role_check.php';require_once __DIR__.'/db.php';
$role=(string)($_SESSION['role']??'');$user=(int)($_SESSION['user_id']??0);if(!hasRole(['Admin','Quality Coordinator','Program Leader','Faculty','Reviewer'])){http_response_code(403);exit('Access denied.');}$canManage=hasRole(['Admin','Quality Coordinator','Program Leader']);$committee=$conn->query("SELECT * FROM committees WHERE committee_name='Consultancy Committee' ORDER BY id LIMIT 1")->fetch();if(!$committee){http_response_code(503);exit('Run database migrations first.');}$committeeId=(int)$committee['id'];$currentStaff=$conn->prepare('SELECT id FROM program_staff WHERE user_id=:user AND employment_status=\'Active\' LIMIT 1');$currentStaff->execute([':user'=>$user]);$currentStaffId=(int)$currentStaff->fetchColumn();
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');if(in_array($action,['setup','schedule','recommend','submit'],true)&&!$canManage){http_response_code(403);exit('Access denied.');}$conn->beginTransaction();try{if($action==='setup'){$chair=(int)($_POST['chair_staff_id']??0);$head=(int)($_POST['department_head_staff_id']??0);$secretary=(int)($_POST['secretary_staff_id']??0);$quorum=min(100,max(1,(int)($_POST['quorum_percent']??50)));foreach([$chair,$head,$secretary]as$sid)if($sid&&!$conn->query("SELECT id FROM program_staff WHERE id=$sid AND employment_status='Active'")->fetchColumn())throw new RuntimeException('Selected officers must be active staff.');$s=$conn->prepare('UPDATE committees SET chair_staff_id=:chair,department_head_staff_id=:head,secretary_staff_id=:secretary,quorum_percent=:quorum,mandate=:mandate,updated_at=NOW() WHERE id=:id');$s->execute([':chair'=>$chair?:null,':head'=>$head?:null,':secretary'=>$secretary?:null,':quorum'=>$quorum,':mandate'=>trim((string)$_POST['mandate']),':id'=>$committeeId]);}elseif($action==='schedule'){$title=trim((string)($_POST['meeting_title']??''));$date=(string)($_POST['meeting_date']??'');$time=(string)($_POST['meeting_time']??'');$memberStmt=$conn->prepare("SELECT staff_id FROM committee_members WHERE committee_id=:committee AND status='Active' AND (end_date IS NULL OR end_date>=CURDATE())");$memberStmt->execute([':committee'=>$committeeId]);$definedMembers=array_map('intval',$memberStmt->fetchAll(PDO::FETCH_COLUMN));$participants=array_values(array_unique(array_merge($definedMembers,array_map('intval',$_POST['participants']??[]))));$agendaLines=array_values(array_filter(array_map('trim',preg_split('/\R/',(string)($_POST['agenda_items']??'')))));if($title===''||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||!$participants||!$agendaLines)throw new RuntimeException('Title, date, participants, and at least one agenda item are required.');$s=$conn->prepare("INSERT INTO committee_meetings(committee_id,meeting_title,meeting_date,meeting_time,location,meeting_mode,agenda,status) VALUES(:committee,:title,:date,:time,:location,:mode,:agenda,'Scheduled')");$s->execute([':committee'=>$committeeId,':title'=>$title,':date'=>$date,':time'=>$time?:null,':location'=>trim((string)($_POST['location']??''))?:null,':mode'=>in_array($_POST['meeting_mode']??'',['In Person','Online','Hybrid'],true)?$_POST['meeting_mode']:'In Person',':agenda'=>implode("\n",$agendaLines)]);$meeting=(int)$conn->lastInsertId();$att=$conn->prepare("INSERT INTO committee_meeting_attendance(meeting_id,staff_id,attendance_status,notes) VALUES(:meeting,:staff,'Invited','Scheduled participant')");foreach($participants as$sid)$att->execute([':meeting'=>$meeting,':staff'=>$sid]);$ag=$conn->prepare('INSERT INTO committee_meeting_agenda_items(meeting_id,item_no,title,status) VALUES(:meeting,:no,:title,\'Planned\')');foreach($agendaLines as$i=>$line)$ag->execute([':meeting'=>$meeting,':no'=>$i+1,':title'=>mb_substr($line,0,255)]);}elseif($action==='recommend'){$meeting=(int)($_POST['meeting_id']??0);$text=trim((string)($_POST['recommendation_text']??''));$check=$conn->prepare('SELECT COUNT(*) FROM committee_meetings WHERE id=:meeting AND committee_id=:committee');$check->execute([':meeting'=>$meeting,':committee'=>$committeeId]);if(!$check->fetchColumn()||$text==='')throw new RuntimeException('Valid meeting and recommendation text are required.');$s=$conn->prepare("INSERT INTO committee_recommendations(meeting_id,committee_id,recommendation_text,approval_stage,priority,status,target_date) VALUES(:meeting,:committee,:text,'Draft',:priority,'Pending',:target)");$s->execute([':meeting'=>$meeting,':committee'=>$committeeId,':text'=>$text,':priority'=>in_array($_POST['priority']??'',['Low','Medium','High','Critical'],true)?$_POST['priority']:'Medium',':target'=>($_POST['target_date']??'')?:null]);}elseif($action==='submit'){$rec=(int)($_POST['recommendation_id']??0);$s=$conn->prepare('SELECT r.*,m.id meeting_id,m.attendance_approved_at,m.required_quorum_count FROM committee_recommendations r JOIN committee_meetings m ON m.id=r.meeting_id WHERE r.id=:rec AND r.committee_id=:committee AND r.approval_stage=\'Draft\' FOR UPDATE');$s->execute([':rec'=>$rec,':committee'=>$committeeId]);$r=$s->fetch();if(!$r)throw new RuntimeException('Draft recommendation not found.');$attendance=$conn->prepare("SELECT staff_id FROM committee_meeting_attendance WHERE meeting_id=:meeting AND attendance_status IN('Present','Online','Late') AND signed_at IS NOT NULL");$attendance->execute([':meeting'=>$r['meeting_id']]);$participants=array_map('intval',$attendance->fetchAll(PDO::FETCH_COLUMN));if(!$r['attendance_approved_at'])throw new RuntimeException('The committee head must approve the signed attendance list before submission.');if(!$participants||count($participants)<(int)$r['required_quorum_count'])throw new RuntimeException('The signed half-plus-one quorum is not met.');if(!$committee['chair_staff_id']||!$committee['department_head_staff_id'])throw new RuntimeException('Committee head and department head must be configured.');$ap=$conn->prepare("INSERT IGNORE INTO committee_recommendation_approvals(recommendation_id,staff_id,approval_role) VALUES(:rec,:staff,:role)");foreach($participants as$sid)$ap->execute([':rec'=>$rec,':staff'=>$sid,':role'=>'Participant']);$ap->execute([':rec'=>$rec,':staff'=>$committee['chair_staff_id'],':role'=>'Committee Head']);$ap->execute([':rec'=>$rec,':staff'=>$committee['department_head_staff_id'],':role'=>'Department Head']);$conn->prepare("UPDATE committee_recommendations SET approval_stage='Participant Review',submitted_by_user_id=:user,submitted_at=NOW() WHERE id=:rec")->execute([':user'=>$user,':rec'=>$rec]);$conn->prepare('UPDATE committee_meetings SET quorum_met=1 WHERE id=:meeting')->execute([':meeting'=>$r['meeting_id']]);}elseif($action==='decide'){$approval=(int)($_POST['approval_id']??0);$decision=(string)($_POST['decision']??'');if(!in_array($decision,['Approved','Rejected','Abstained'],true)||!$currentStaffId)throw new RuntimeException('A linked active staff account and valid decision are required.');$s=$conn->prepare("SELECT a.*,r.approval_stage FROM committee_recommendation_approvals a JOIN committee_recommendations r ON r.id=a.recommendation_id WHERE a.id=:approval AND a.staff_id=:staff AND a.decision='Pending' FOR UPDATE");$s->execute([':approval'=>$approval,':staff'=>$currentStaffId]);$a=$s->fetch();if(!$a)throw new RuntimeException('Approval is not assigned to the signed-in staff member.');$required=['Participant'=>'Participant Review','Committee Head'=>'Committee Head Review','Department Head'=>'Department Head Review'];if($a['approval_stage']!==$required[$a['approval_role']])throw new RuntimeException('This approval is not at its active stage.');$conn->prepare('UPDATE committee_recommendation_approvals SET decision=:decision,comment=:comment,decided_at=NOW() WHERE id=:id')->execute([':decision'=>$decision,':comment'=>trim((string)($_POST['comment']??''))?:null,':id'=>$approval]);$rec=(int)$a['recommendation_id'];if($decision==='Rejected')$conn->prepare("UPDATE committee_recommendations SET approval_stage='Rejected',status='Rejected' WHERE id=:id")->execute([':id'=>$rec]);elseif($a['approval_role']==='Participant'){$pending=$conn->query("SELECT COUNT(*) FROM committee_recommendation_approvals WHERE recommendation_id=$rec AND approval_role='Participant' AND decision='Pending'")->fetchColumn();if(!$pending)$conn->prepare("UPDATE committee_recommendations SET approval_stage='Committee Head Review' WHERE id=:id")->execute([':id'=>$rec]);}elseif($a['approval_role']==='Committee Head')$conn->prepare("UPDATE committee_recommendations SET approval_stage='Department Head Review' WHERE id=:id")->execute([':id'=>$rec]);else$conn->prepare("UPDATE committee_recommendations SET approval_stage='Approved',status='Approved',approved_at=NOW() WHERE id=:id")->execute([':id'=>$rec]);}else throw new RuntimeException('Invalid action.');QualitySystem\Security\AuditLogger::record($conn,'consultancy_committee_'.$action,'allowed','Committees',[],'committee',$committeeId);$conn->commit();header('Location: /consultancy_committee.php');exit;}catch(Throwable$e){if($conn->inTransaction())$conn->rollBack();$error=$e->getMessage();}}
$committee=$conn->query("SELECT c.*,chair.full_name chair_name,dh.full_name department_head_name,sec.full_name secretary_name FROM committees c LEFT JOIN program_staff chair ON chair.id=c.chair_staff_id LEFT JOIN program_staff dh ON dh.id=c.department_head_staff_id LEFT JOIN program_staff sec ON sec.id=c.secretary_staff_id WHERE c.id=$committeeId")->fetch();$staff=$conn->query("SELECT id,full_name,academic_rank,role_in_program,email FROM program_staff WHERE employment_status='Active' ORDER BY full_name")->fetchAll();$meetings=$conn->query("SELECT m.*,(SELECT COUNT(*) FROM committee_meeting_attendance a WHERE a.meeting_id=m.id) participant_count,(SELECT COUNT(*) FROM committee_meeting_agenda_items g WHERE g.meeting_id=m.id) agenda_count FROM committee_meetings m WHERE m.committee_id=$committeeId ORDER BY m.meeting_date DESC,m.id DESC")->fetchAll();$recommendations=$conn->query("SELECT r.*,m.meeting_title,(SELECT COUNT(*) FROM committee_recommendation_approvals a WHERE a.recommendation_id=r.id) approval_count,(SELECT COUNT(*) FROM committee_recommendation_approvals a WHERE a.recommendation_id=r.id AND a.decision='Approved') approved_count FROM committee_recommendations r JOIN committee_meetings m ON m.id=r.meeting_id WHERE r.committee_id=$committeeId ORDER BY r.id DESC")->fetchAll();$myApprovals=[];if($currentStaffId){$s=$conn->prepare("SELECT a.*,r.recommendation_text FROM committee_recommendation_approvals a JOIN committee_recommendations r ON r.id=a.recommendation_id WHERE a.staff_id=:staff AND a.decision='Pending' ORDER BY a.id");$s->execute([':staff'=>$currentStaffId]);$myApprovals=$s->fetchAll();}$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Consultancy Committee</title><link rel="stylesheet" href="/assets/style.css"><style>main{max-width:1300px;margin:auto;padding:1rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:1rem}.panel{border:1px solid #ccd3da;border-radius:10px;padding:1rem;margin:1rem 0}.staff-list{max-height:260px;overflow:auto;border:1px solid #ccd3da;padding:.5rem}.staff-list label{display:block;font-weight:400}label{display:block;font-weight:700}input,select,textarea{width:100%;box-sizing:border-box}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ccd3da;padding:.6rem;vertical-align:top}.flow{padding:1rem;background:#eef2f5;border-radius:8px}@media(max-width:800px){.grid{grid-template-columns:1fr}}</style></head><body><?php require __DIR__.'/nav.php';?><main><h1>Consultancy Committee</h1><p class="flow"><strong>Approval flow:</strong> Draft → quorum validation → all participating staff endorse → committee head approves → department head approves → Approved. Any rejection stops the workflow.</p><?php if(isset($error)):?><p role="alert"><?=$h($error)?></p><?php endif;?><div class="panel"><strong>Committee head:</strong> <?=$h($committee['chair_name']?:'Not assigned')?> · <strong>Department head:</strong> <?=$h($committee['department_head_name']?:'Not assigned')?> · <strong>Secretary:</strong> <?=$h($committee['secretary_name']?:'Not assigned')?> · <strong>Quorum:</strong> <?=(int)$committee['quorum_percent']?>%</div><?php if($canManage):?><div class="grid"><form method="post" class="panel"><?=csrfField()?><input type="hidden" name="action" value="setup"><h2>Committee governance</h2><?php foreach([['chair_staff_id','Committee head'],['department_head_staff_id','Department head'],['secretary_staff_id','Secretary']]as[$name,$label]):?><label><?=$label?><select name="<?=$name?>"><option value="">Select</option><?php foreach($staff as$s):?><option value="<?=(int)$s['id']?>" <?=((int)($committee[$name]??0)===(int)$s['id'])?'selected':''?>><?=$h($s['full_name'])?></option><?php endforeach;?></select></label><?php endforeach;?><label>Quorum percent<input type="number" min="1" max="100" name="quorum_percent" value="<?=(int)$committee['quorum_percent']?>"></label><label>Mandate<textarea name="mandate" rows="4"><?=$h($committee['mandate'])?></textarea></label><button>Save governance</button></form><form method="post" class="panel"><?=csrfField()?><input type="hidden" name="action" value="schedule"><h2>Schedule meeting</h2><label>Meeting title<input name="meeting_title" required></label><label>Date<input type="date" name="meeting_date" required></label><label>Time<input type="time" name="meeting_time"></label><label>Mode<select name="meeting_mode"><option>In Person</option><option>Online</option><option>Hybrid</option></select></label><label>Location or link<input name="location"></label><label>Agenda items, one per line<textarea name="agenda_items" rows="6" required></textarea></label><strong>Participants from available staff</strong><div class="staff-list"><?php foreach($staff as$s):?><label><input type="checkbox" name="participants[]" value="<?=(int)$s['id']?>"> <?=$h($s['full_name'].' — '.$s['academic_rank'])?></label><?php endforeach;?></div><button>Schedule meeting</button></form></div><form method="post" class="panel"><?=csrfField()?><input type="hidden" name="action" value="recommend"><h2>Add recommendation</h2><label>Meeting<select name="meeting_id" required><?php foreach($meetings as$m):?><option value="<?=(int)$m['id']?>"><?=$h($m['meeting_date'].' — '.$m['meeting_title'])?></option><?php endforeach;?></select></label><label>Recommendation<textarea name="recommendation_text" rows="4" required></textarea></label><label>Priority<select name="priority"><option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option></select></label><label>Target date<input type="date" name="target_date"></label><button>Add draft recommendation</button></form><?php endif;?><h2>Meetings</h2><table><thead><tr><th>Date</th><th>Meeting</th><th>Mode</th><th>Participants</th><th>Agenda</th><th>Attendance/minutes</th></tr></thead><tbody><?php foreach($meetings as$m):?><tr><td><?=$h($m['meeting_date'].' '.$m['meeting_time'])?></td><td><?=$h($m['meeting_title'])?></td><td><?=$h($m['meeting_mode'])?></td><td><?=(int)$m['participant_count']?></td><td><?=(int)$m['agenda_count']?></td><td><a href="/manage_committee_meeting_attendance.php?id=<?=(int)$m['id']?>">Attendance</a> · <a href="/committee_meeting_profile.php?id=<?=(int)$m['id']?>">Meeting record</a></td></tr><?php endforeach;?></tbody></table><h2>Recommendations</h2><table><thead><tr><th>Recommendation</th><th>Stage</th><th>Approvals</th><th>Action</th></tr></thead><tbody><?php foreach($recommendations as$r):?><tr><td><?=$h($r['recommendation_text'])?><br><small><?=$h($r['meeting_title'])?></small></td><td><?=$h($r['approval_stage'])?></td><td><?=(int)$r['approved_count']?> / <?=(int)$r['approval_count']?></td><td><?php if($canManage&&$r['approval_stage']==='Draft'):?><form method="post"><?=csrfField()?><input type="hidden" name="action" value="submit"><input type="hidden" name="recommendation_id" value="<?=(int)$r['id']?>"><button>Submit after attendance</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table><?php if($myApprovals):?><h2>My pending approvals</h2><?php foreach($myApprovals as$a):?><form method="post" class="panel"><?=csrfField()?><input type="hidden" name="action" value="decide"><input type="hidden" name="approval_id" value="<?=(int)$a['id']?>"><p><strong><?=$h($a['approval_role'])?>:</strong> <?=$h($a['recommendation_text'])?></p><label>Comment<input name="comment"></label><button name="decision" value="Approved">Approve</button><button name="decision" value="Rejected">Reject</button><button name="decision" value="Abstained">Abstain</button></form><?php endforeach;?><?php endif;?></main></body></html>
